 n=st['n'];crop=im.crop(s['board']['slots'][str(n)]);crop=crop.resize((round(crop.width*k),round(crop.height*k)),Image.Resampling.LANCZOS);p=dest/f'{n:03d}.jpg';crop.save(p,quality=94);p.chmod(0o600)
 data.append({'n':n,'photo':'../../'+st['dry']['src'],'before':'../../'+st['app']['0515e56a']['src'],'after':f'{n:03d}.jpg'})
